// ═══════════════════════════════════════════════════════════════
// Build rotating AI/Tech search queries by day of week
// Each day covers a different AI domain — keeps digest fresh
// ═══════════════════════════════════════════════════════════════
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Sun 1=Mon 2=Tue 3=Wed 4=Thu 5=Fri 6=Sat

const QUERY_SETS = [
  // Sunday — Weekly AI news recap
  { q: 'artificial intelligence news this week AI roundup', order: 'relevance', label: 'Weekly AI Roundup' },
  // Monday — LLM & models
  { q: 'large language model LLM GPT Claude Gemini 2025 new release', order: 'relevance', label: 'LLMs & Models' },
  // Tuesday — AI tools & productivity
  { q: 'AI tools productivity automation workflow 2025', order: 'viewCount', label: 'AI Tools & Productivity' },
  // Wednesday — AI image/video generation
  { q: 'AI image generation video generation Sora Midjourney latest', order: 'relevance', label: 'AI Generation' },
  // Thursday — AI agents & coding
  { q: 'AI agent autonomous coding Claude Cursor Copilot tutorial', order: 'relevance', label: 'AI Agents & Code' },
  // Friday — AI business & startups
  { q: 'AI startup product launch business automation 2025', order: 'viewCount', label: 'AI Business' },
  // Saturday — Deep dives & tutorials
  { q: 'machine learning deep learning tutorial explained 2025', order: 'relevance', label: 'ML Tutorials' },
];

const qs = QUERY_SETS[dayOfWeek];

// Published in last 48 hours for fresh content
const publishedAfter = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString();

const dateStr = now.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'America/New_York'
});

console.log('Search query:', qs.q);
console.log('Date:', dateStr);

return [{ json: {
  q: qs.q,
  order: qs.order,
  label: qs.label,
  publishedAfter,
  dateStr,
  dayOfWeek,
} }];

const searchResp = $input.first().json;
const contextData = $('Code: Build Search Query').first().json;

if (!searchResp.items || searchResp.items.length === 0) {
  throw new Error('YouTube Search returned no results. Check API key and quota. Error: ' + JSON.stringify(searchResp).slice(0, 300));
}

// Extract unique video IDs and basic info
const seen = new Set();
const videos = [];

for (const item of searchResp.items) {
  const vid = item.id?.videoId;
  if (!vid || seen.has(vid)) continue;
  seen.add(vid);

  videos.push({
    videoId: vid,
    title: item.snippet?.title || '',
    channel: item.snippet?.channelTitle || '',
    description: (item.snippet?.description || '').slice(0, 500),
    publishedAt: item.snippet?.publishedAt || '',
    thumbnail: item.snippet?.thumbnails?.high?.url ||
               item.snippet?.thumbnails?.medium?.url ||
               item.snippet?.thumbnails?.default?.url || '',
  });
}

// Take top 10 unique videos
const top = videos.slice(0, 10);
const videoIds = top.map(v => v.videoId).join(',');

console.log(`Found ${searchResp.items.length} results, ${top.length} unique taken`);

return [{ json: {
  videos: top,
  videoIds,
  count: top.length,
  label: contextData.label,
  dateStr: contextData.dateStr,
} }];

const detailsResp = $('HTTP: YouTube Video Details').first().json;
const searchData  = $('Code: Extract & Filter Video IDs').first().json;

if (!detailsResp.items || detailsResp.items.length === 0) {
  throw new Error('YouTube Video Details returned no items. Response: ' + JSON.stringify(detailsResp).slice(0, 300));
}

// Helper: parse ISO 8601 duration (PT4M30S)
function parseDuration(iso) {
  if (!iso) return 'Unknown';
  const m = iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!m) return iso;
  const h = parseInt(m[1] || 0);
  const min = parseInt(m[2] || 0);
  const sec = parseInt(m[3] || 0);
  if (h > 0) return `${h}h ${min}m`;
  if (min > 0) return `${min}m ${sec > 0 ? sec + 's' : ''}`;
  return `${sec}s`;
}

// Helper: format large numbers
function fmt(n) {
  const num = parseInt(n || 0);
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000)    return (num / 1000).toFixed(1) + 'K';
  return num.toLocaleString();
}

// Map search thumbnails by videoId (higher quality than what details returns)
const thumbMap = {};
for (const sv of (searchData.videos || [])) {
  thumbMap[sv.videoId] = sv.thumbnail;
}

// Build enriched profiles
const profiles = [];
for (const item of detailsResp.items) {
  const snippet = item.snippet || {};
  const stats   = item.statistics || {};
  const content = item.contentDetails || {};
  const vid     = item.id;

  const fullDesc = (snippet.description || '').slice(0, 2000);
  const tags     = (snippet.tags || []).slice(0, 12).join(', ');

  profiles.push({
    videoId:     vid,
    title:       snippet.title || '',
    channel:     snippet.channelTitle || '',
    publishedAt: snippet.publishedAt || '',
    duration:    parseDuration(content.duration),
    views:       fmt(stats.viewCount),
    likes:       fmt(stats.likeCount),
    comments:    fmt(stats.commentCount),
    description: fullDesc,
    tags:        tags,
    thumbnail:   thumbMap[vid] || `https://i.ytimg.com/vi/${vid}/hqdefault.jpg`,
    url:         `https://www.youtube.com/watch?v=${vid}`,
  });
}

if (profiles.length === 0) {
  throw new Error('No video profiles built after enrichment. Something is wrong with the API response.');
}

console.log(`Built ${profiles.length} rich video profiles for Claude`);

return [{ json: {
  profiles,
  count:   profiles.length,
  dateStr: searchData.dateStr,
  label:   searchData.label,
} }];

const response   = $input.first().json;
const videoData  = $('Code: Build Rich Video Profiles').first().json;

// Extract Groq's text response (OpenAI-compatible format)
// Groq returns: response.choices[0].message.content
let raw = '';
try {
  raw = response.choices[0].message.content;
} catch(e) {
  console.log('Groq response error:', JSON.stringify(response).slice(0, 400));
  throw new Error('Groq API call failed. Check your free API key at console.groq.com. Response: ' + JSON.stringify(response).slice(0, 400));
}

// Strip any markdown code fences Groq may add despite instructions
let digest;
try {
  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/,      '')
    .replace(/\s*```$/,      '')
    .trim();
  digest = JSON.parse(cleaned);
} catch(e) {
  console.log('JSON parse failed. Raw response (first 500):', raw.slice(0, 500));
  // Fallback: build basic digest from raw video profiles
  digest = {
    digest_title: 'AI Tech Digest — ' + videoData.dateStr,
    theme: videoData.label,
    headline_summary: 'Today\'s AI digest covers ' + videoData.count + ' fresh videos on: ' + videoData.label + '. AI summarization had an issue — video list below.',
    top_pick: {
      videoId:      videoData.profiles[0]?.videoId || '',
      title:        videoData.profiles[0]?.title || '',
      channel:      videoData.profiles[0]?.channel || '',
      url:          videoData.profiles[0]?.url || '',
      why_top_pick: 'Most relevant video for today\'s AI theme.',
    },
    videos: videoData.profiles.map(p => ({
      videoId:         p.videoId,
      title:           p.title,
      channel:         p.channel,
      duration:        p.duration,
      views:           p.views,
      url:             p.url,
      summary:         p.description.slice(0, 200) + '...',
      key_takeaways:   ['Watch the full video for complete insights'],
      relevance_score: 7,
      category:        'Video',
      tags:            ['AI', 'Tech'],
    })),
    todays_themes:   ['Artificial Intelligence', 'Machine Learning', 'Tech'],
    tools_mentioned: [],
    key_companies:   [],
    telegram_summary: '\uD83E\uDD16 AI Tech Digest | ' + videoData.count + ' videos | ' + videoData.dateStr + '\n\nCheck your email for full summaries!',
    one_liner: 'AI keeps moving — ' + videoData.count + ' key videos summarized for you today.',
  };
}

// Guarantee all expected arrays exist
if (!Array.isArray(digest.videos))          digest.videos = [];
if (!Array.isArray(digest.todays_themes))   digest.todays_themes = [];
if (!Array.isArray(digest.tools_mentioned)) digest.tools_mentioned = [];
if (!Array.isArray(digest.key_companies))   digest.key_companies = [];

console.log('Groq digest parsed. Videos:', digest.videos.length, '| Title:', digest.digest_title);

return [{ json: {
  digest,
  profiles: videoData.profiles,
  dateStr:  videoData.dateStr,
  label:    videoData.label,
} }];

const { digest, profiles, dateStr, label } = $input.first().json;

// Build profile lookup for thumbnails
const thumbMap = {};
for (const p of (profiles || [])) {
  thumbMap[p.videoId] = p.thumbnail;
}

// Category color map
const catColors = {
  Tutorial:  { bg: '#e3f2fd', color: '#1565c0' },
  News:      { bg: '#fce4ec', color: '#c62828' },
  Analysis:  { bg: '#e8f5e9', color: '#2e7d32' },
  Demo:      { bg: '#fff3e0', color: '#e65100' },
  Interview: { bg: '#f3e5f5', color: '#6a1b9a' },
  Review:    { bg: '#e0f2f1', color: '#00695c' },
};
function catBadge(cat) {
  const c = catColors[cat] || { bg: '#f5f5f5', color: '#555' };
  return `<span style="background:${c.bg};color:${c.color};padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;letter-spacing:0.5px;">${cat || 'Video'}</span>`;
}

// Star rating
function stars(n) {
  const s = Math.min(Math.max(Math.round(n || 7), 1), 10);
  return '\u2605'.repeat(s) + '\u2606'.repeat(10 - s);
}

// Video cards HTML
const videoCards = (digest.videos || []).map((v, i) => {
  const thumb = thumbMap[v.videoId] || `https://i.ytimg.com/vi/${v.videoId}/hqdefault.jpg`;
  const takeaways = (v.key_takeaways || []).map(t => `<li style="margin:5px 0;color:#444;">${t}</li>`).join('');
  const vtags = (v.tags || []).slice(0, 4).map(t =>
    `<span style="background:#f1f3f4;color:#5f6368;padding:2px 8px;border-radius:10px;font-size:11px;margin:2px;display:inline-block;">${t}</span>`
  ).join('');

  return `
  <div style="border:1px solid #e8eaed;border-radius:12px;margin-bottom:20px;overflow:hidden;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,0.06);">
    <table cellpadding="0" cellspacing="0" width="100%">
      <tr>
        <td width="200" valign="top" style="padding:0;">
          <a href="${v.url}" target="_blank">
            <img src="${thumb}" width="200" height="113" alt="${v.title}" style="display:block;object-fit:cover;" />
          </a>
        </td>
        <td valign="top" style="padding:14px 16px;">
          <p style="margin:0 0 4px;font-size:11px;color:#888;">#${i + 1} &nbsp;${catBadge(v.category)}</p>
          <a href="${v.url}" target="_blank" style="text-decoration:none;">
            <h3 style="margin:0 0 6px;color:#1a1a1a;font-size:15px;line-height:1.4;">${v.title}</h3>
          </a>
          <p style="margin:0 0 8px;color:#888;font-size:12px;">
            \uD83D\uDCFA ${v.channel} &nbsp;\u2022&nbsp; \u23F1 ${v.duration} &nbsp;\u2022&nbsp; \uD83D\uDC41 ${v.views} views
          </p>
          <p style="margin:0 0 10px;color:#333;font-size:13px;line-height:1.65;">${v.summary}</p>
          <div style="margin-bottom:8px;">${vtags}</div>
          <p style="margin:0;font-size:11px;color:#aaa;">Relevance: ${stars(v.relevance_score)}</p>
        </td>
      </tr>
    </table>
    <div style="background:#f8f9fa;padding:12px 16px;border-top:1px solid #e8eaed;">
      <p style="margin:0 0 6px;font-size:12px;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.5px;">\uD83D\uDCA1 Key Takeaways</p>
      <ul style="margin:0;padding-left:18px;">${takeaways}</ul>
    </div>
    <div style="padding:10px 16px;">
      <a href="${v.url}" target="_blank" style="background:#ff0000;color:#fff;padding:7px 16px;border-radius:6px;text-decoration:none;font-size:12px;font-weight:700;display:inline-block;">\u25B6 Watch on YouTube</a>
    </div>
  </div>`;
}).join('');

// Top Pick section
const tp = digest.top_pick;
const topPickHtml = tp ? `
<div style="background:linear-gradient(135deg,#667eea,#764ba2);border-radius:14px;padding:24px;margin:24px 0;color:#fff;">
  <p style="margin:0 0 8px;font-size:11px;letter-spacing:2px;opacity:0.8;text-transform:uppercase;">\u2B50 Today's Top Pick</p>
  <h2 style="margin:0 0 8px;font-size:18px;line-height:1.4;">${tp.title}</h2>
  <p style="margin:0 0 6px;opacity:0.85;font-size:13px;">\uD83D\uDCFA ${tp.channel}</p>
  <p style="margin:0 0 18px;font-size:14px;line-height:1.6;opacity:0.95;">${tp.why_top_pick}</p>
  <a href="${tp.url}" target="_blank" style="background:#fff;color:#764ba2;padding:10px 22px;border-radius:8px;text-decoration:none;font-weight:700;font-size:13px;display:inline-block;">\u25B6 Watch Now</a>
</div>` : '';

// Pills for themes, tools, companies
function pills(arr, bg, color) {
  return (arr || []).map(t =>
    `<span style="background:${bg};color:${color};padding:5px 12px;border-radius:20px;font-size:12px;margin:3px;display:inline-block;">${t}</span>`
  ).join('');
}

const themePills   = pills(digest.todays_themes,  '#e8eaf6', '#3949ab');
const toolPills    = pills(digest.tools_mentioned, '#e8f5e9', '#2e7d32');
const companyPills = pills(digest.key_companies,   '#fff3e0', '#e65100');

// Full HTML email
const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${digest.digest_title}</title></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;max-width:680px;margin:0 auto;background:#f1f3f4;padding:20px 0;">

<!-- HEADER -->
<div style="background:linear-gradient(135deg,#0f0c29,#302b63,#24243e);padding:40px 30px;text-align:center;border-radius:14px 14px 0 0;">
  <div style="font-size:52px;margin-bottom:10px;">🤖</div>
  <h1 style="color:#fff;margin:0 0 6px;font-size:26px;font-weight:800;letter-spacing:-0.5px;">AI Tech Daily Digest</h1>
  <p style="color:rgba(255,255,255,0.65);margin:0 0 8px;font-size:14px;">${dateStr}</p>
  <p style="color:#a78bfa;margin:0;font-size:13px;font-style:italic;">"${digest.one_liner || 'Staying sharp in the age of AI.'}"</p>
</div>

<!-- BODY -->
<div style="background:#fff;padding:28px 30px;">

  <!-- HEADLINE SUMMARY -->
  <div style="background:#e8eaf6;border-left:4px solid #3949ab;padding:16px 18px;border-radius:0 10px 10px 0;margin-bottom:24px;">
    <p style="margin:0 0 4px;font-size:11px;font-weight:700;color:#3949ab;text-transform:uppercase;letter-spacing:1px;">📋 Today's AI Briefing — ${label}</p>
    <p style="margin:0;font-size:15px;line-height:1.7;color:#222;">${digest.headline_summary}</p>
  </div>

  <!-- TOP PICK -->
  ${topPickHtml}

  <!-- THEMES & TOOLS -->
  ${themePills ? `<div style="margin-bottom:18px;"><p style="font-size:12px;font-weight:700;color:#555;text-transform:uppercase;letter-spacing:0.5px;margin:0 0 8px;">📌 Today's Themes</p>${themePills}</div>` : ''}
  ${toolPills  ? `<div style="margin-bottom:18px;"><p style="font-size:12px;font-weight:700;color:#555;text-transform:uppercase;letter-spacing:0.5px;margin:0 0 8px;">🛠 AI Tools Mentioned</p>${toolPills}</div>` : ''}
  ${companyPills ? `<div style="margin-bottom:18px;"><p style="font-size:12px;font-weight:700;color:#555;text-transform:uppercase;letter-spacing:0.5px;margin:0 0 8px;">🏢 Key Companies</p>${companyPills}</div>` : ''}

  <!-- DIVIDER -->
  <h2 style="color:#1a1a1a;font-size:18px;border-bottom:2px solid #f0f0f0;padding-bottom:10px;margin-top:28px;">📺 All Videos Today (${(digest.videos || []).length})</h2>

  <!-- VIDEO CARDS -->
  ${videoCards}

</div>

<!-- FOOTER -->
<div style="background:#1a1a2e;padding:20px 30px;text-align:center;border-radius:0 0 14px 14px;">
  <p style="color:rgba(255,255,255,0.4);font-size:11px;margin:0;">🤖 AI Tech Digest &mdash; Powered by Claude AI + YouTube Data API &mdash; Auto-generated daily at 8AM ET</p>
</div>

</body></html>`;

// Plain text fallback
const plainText = [
  `AI TECH DIGEST — ${dateStr}`,
  `Theme: ${label}`,
  '',
  digest.headline_summary,
  '',
  '--- TODAY\'S VIDEOS ---',
  ...(digest.videos || []).map((v, i) =>
    `${i + 1}. ${v.title}\n   ${v.channel} | ${v.duration} | ${v.views} views\n   ${v.url}\n   ${v.summary}\n`
  ),
].join('\n');

return [{ json: {
  html,
  plainText,
  subject: digest.digest_title || `AI Tech Digest — ${dateStr}`,
  telegramMsg: digest.telegram_summary || `\uD83E\uDD16 AI Tech Digest | ${(digest.videos || []).length} videos summarized!\n\n${digest.headline_summary?.slice(0, 300) || ''}`,
  videoCount: (digest.videos || []).length,
} }];

