const telegramResult = $('HTTP: Send Telegram Digest').first().json;
const emailResult    = $('HTTP: Send Email via Gmail SMTP').first().json;
const htmlData       = $('Code: Format HTML Email').first().json;
const digestData     = $('Code: Parse Groq Digest').first().json;

console.log('\u2550'.repeat(50));
console.log('\u2705 WF-C AI TECH YOUTUBE DIGEST — COMPLETE');
console.log('   Date:         ', digestData.dateStr);
console.log('   Theme:        ', digestData.label);
console.log('   Videos:       ', htmlData.videoCount);
console.log('   Subject:      ', htmlData.subject);
console.log('   Telegram:     ', telegramResult?.ok ? 'SENT \u2705' : 'ERROR \u274C — ' + JSON.stringify(telegramResult).slice(0, 100));
console.log('   Email:        ', emailResult ? 'SENT \u2705' : 'CHECK SMTP SETTINGS');
console.log('\u2550'.repeat(50));

return [{ json: {
  success:          true,
  videosProcessed:  htmlData.videoCount,
  subject:          htmlData.subject,
  telegramStatus:   telegramResult?.ok ? 'sent' : 'error',
  emailStatus:      emailResult ? 'sent' : 'check_smtp',
  completedAt:      new Date().toISOString(),
} }];
